int mod,n,m,i,j,k,c[505][505],f[505],g[505],dp[505][505][2],ans;
int main()
{
	read(n);read(m);read(mod);
	c[0][0]=1;rep(i,n){c[i][0]=1;rep(j,i)c[i][j]=(c[i-1][j]+c[i-1][j-1])%mod;}
	f[0]=1;
	rep(i,n){
		rep0(j,i){
			k=i-j-1;
			f[i]=(f[i]+1ll*f[j]*f[k]%mod*(i+1)%mod*c[i-1][j])%mod; 
			g[i]=(g[i]+1ll*g[j]*f[k]%mod*(i+1)%mod*c[i-1][j])%mod; 
			g[i]=(g[i]+1ll*f[j]*g[k]%mod*(i+1)%mod*c[i-1][j])%mod; 
			g[i]=(g[i]+1ll*f[j]*f[k]%mod*c[i-1][j]%mod*((j*(j+1)/2)+(k*(k+1)/2)))%mod;
		}
	}
	dp[0][0][1]=1;
	rep0(i,n){
		rep0(j,i+1){
			dp[i+1][j][1]=(0ll+dp[i+1][j][1]+dp[i][j][0]+dp[i][j][1])%mod;
