				dp[i+k][j+k][0]=(dp[i+k][j+k][0]+1ll*dp[i][j][1]*f[k]%mod*c[j+k][j])%mod;
			}
		}
	}
	rep(j,n)rep(i,j){
		int rem=m-(j-i+1);
		if(rem<0) continue;
		rep0(k,rem+1){
			ans=(ans+1ll*g[j-i+1]*dp[i-1][k][1]%mod*dp[n-j][rem-k][1]%mod*c[m][rem]%mod*c[rem][k])%mod;
		} 
	}
	cout<<ans<<endl;
	return 0;
}
